<?php
require 'config.php'; require_login(); verify_csrf(); $pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){$id=(int)($_POST['id']??0);$d=[trim($_POST['nombre']),trim($_POST['documento']),trim($_POST['correo']),trim($_POST['telefono'])];if($id){$s=$pdo->prepare('UPDATE lectores SET nombre=?,documento=?,correo=?,telefono=? WHERE id=?');$s->execute([...$d,$id]);flash('Lector actualizado.');}else{$s=$pdo->prepare('INSERT INTO lectores(nombre,documento,correo,telefono) VALUES(?,?,?,?)');$s->execute($d);flash('Lector registrado.');}header('Location: lectores.php');exit;}
if(isset($_GET['eliminar'])){try{$s=$pdo->prepare('DELETE FROM lectores WHERE id=?');$s->execute([(int)$_GET['eliminar']]);flash('Lector eliminado.');}catch(PDOException $e){flash('No se puede eliminar: tiene préstamos asociados.','danger');}header('Location: lectores.php');exit;}
$edit=null;if(isset($_GET['editar'])){$s=$pdo->prepare('SELECT * FROM lectores WHERE id=?');$s->execute([(int)$_GET['editar']]);$edit=$s->fetch();}
$rows=$pdo->query('SELECT * FROM lectores ORDER BY id DESC')->fetchAll();$pageTitle='Gestión de lectores';require 'partials/header.php';
?>
<div class="row g-4"><div class="col-lg-4"><div class="card border-0 shadow-sm"><div class="card-header bg-white fw-semibold"><?= $edit?'Editar lector':'Registrar lector'?></div><div class="card-body"><form method="post"><?=csrf_field()?><input type="hidden" name="id" value="<?=e($edit['id']??'')?>"><div class="mb-3"><label class="form-label">Nombre completo</label><input class="form-control" name="nombre" required value="<?=e($edit['nombre']??'')?>"></div><div class="mb-3"><label class="form-label">DNI / documento</label><input class="form-control" name="documento" required value="<?=e($edit['documento']??'')?>"></div><div class="mb-3"><label class="form-label">Correo</label><input type="email" class="form-control" name="correo" value="<?=e($edit['correo']??'')?>"></div><div class="mb-3"><label class="form-label">Teléfono</label><input class="form-control" name="telefono" value="<?=e($edit['telefono']??'')?>"></div><button class="btn btn-primary">Guardar</button> <a href="lectores.php" class="btn btn-light">Limpiar</a></form></div></div></div>
<div class="col-lg-8"><div class="card border-0 shadow-sm"><div class="card-header bg-white fw-semibold">Lectores registrados (<?=count($rows)?>)</div><div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead><tr><th>Nombre</th><th>Documento</th><th>Correo</th><th>Teléfono</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['nombre'])?></td><td><?=e($r['documento'])?></td><td><?=e($r['correo'])?></td><td><?=e($r['telefono'])?></td><td class="text-nowrap"><a class="btn btn-sm btn-outline-primary" href="?editar=<?=$r['id']?>">Editar</a> <a class="btn btn-sm btn-outline-danger" onclick="return confirm('¿Eliminar lector?')" href="?eliminar=<?=$r['id']?>">Eliminar</a></td></tr><?php endforeach;?></tbody></table></div></div></div></div>
<?php require 'partials/footer.php'; ?>
